content:
.fire-btn:active, .fire-btn.active {
  background: rgba(255,80,80,0.95);
  border-color: rgba(255,200,200,0.9);
}

/* 触屏设备自动显示虚拟控制 */
@media (hover: none) and (pointer: coarse) {
  #touchControls:not(.hidden) { display: block; }
}

/* 小屏设备 / 容器内始终显示虚拟控制（兜底，阈值与 main.js 一致） */
@media (max-width: 1024px) {
  #touchControls:not(.hidden) { display: block; }
}

/* 左上：武器切换 + 暂停 */
#topControls {
  position: absolute; left: calc(16px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); top: calc(80px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  display: flex; flex-direction: row; gap: 8px;
  pointer-events: auto;
  z-index: 50;
}
.top-btn {
  width: 44px; height: 44px;
  background: rgba(255,255,255,0.15);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 8px;
  color: #fff; font-size: 18px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  touch-action: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-shadow: 0 1px 2px rgba(0,0,0,0.6);
}
.top-btn:active, .top-btn.active {
  background: rgba(245,181,58,0.6);
  border-color: rgba(245,181,58,0.9);
}

/* ========== 小地图 ========== */
#minimapWrap {
  position: absolute; right: calc(16px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); top: calc(80px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  width: 160px; height: 160px;
  background: rgba(0,0,0,0.65);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 8px;
  z-index: 40;
  overflow: hidden;
}
#minimap {
  width: 100%; height: 100%;
  display: block;
}

/* ========== 横竖屏自适应布局 ========== */

/* ---- 竖屏（手机竖拿）---- */
@media (orientation: portrait) {
  .panel {
    min-width: 0;
    width: min(440px, calc(100vw - 24px));
    padding: 28px 20px;
  }
  .title { font-size: 40px; }
  .subtitle { font-size: 12px; margin-bottom: 20px; }
  .btn { padding: 12px 40px; font-size: 16px; }
  .controls { font-size: 12px; }
  .tip { font-size: 11px; }

  /* 顶栏：收窄居中 */
  #topbar {
    top: calc(8px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
    transform: translateX(-50%) scale(0.82);
    transform-origin: top center;
  }
  .score-block { padding: 6px 14px; }
  .score-block .num { font-size: 18px; }
  .score-block.center .label { font-size: 12px; }

  /* 左上：武器切换（缩窄，避开顶栏） */
  #topControls {
    left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px)));
    top: calc(56px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
    gap: 6px;
  }
  .top-btn { width: 40px; height: 40px; font-size: 16px; }

  /* 右上：小地图缩小 */
  #minimapWrap {
    width: 108px; height: 108px;
    right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px)));
    top: calc(56px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  }

  /* 左下：血量护甲收窄 */
  #vitals { left: 12px; bottom: calc(10px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .vital .bar { width: 120px; height: 12px; }
  .vital span:not(.icon) { width: 30px; font-size: 14px; }
  .vital .icon { font-size: 16px; width: 20px; }

  /* 右下：武器弹药收窄，为动作键让位 */
  #weaponHud { right: 12px; bottom: calc(10px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  #ammo { font-size: 28px; }
  #weaponName { font-size: 12px; }
  #weaponSlots { gap: 5px; }
  .slot { padding: 2px 7px; font-size: 10px; }

  /* D-pad 缩小、上移到血量条上方 */
  #dpad {
    width: 108px; height: 108px;
    left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px)));
    bottom: calc(96px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
    gap: 4px;
  }
  .dpad-btn { font-size: 16px; border-radius: 8px; }

  /* 动作键（含 FIRE）上移，避开武器 HUD */
  #actionBtns {
    right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px)));
    bottom: calc(150px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
    gap: 8px;
  }
  .act-btn { width: 48px; height: 48px; font-size: 14px; }
  .fire-btn { width: 64px; height: 64px; font-size: 16px; }

  #toast { bottom: 170px; font-size: 14px; }
  #killFeed { top: 104px; left: 12px; }
}

/* ---- 横屏低高度（手机横拿，高度 ≤ 520px）---- */
@media (orientation: landscape) and (max-height: 520px) {
  .panel {
    min-width: 0;
    width: min(560px, 92vw);
    padding: 20px 28px;
  }
  .title { font-size: 34px; }
  .subtitle { font-size: 12px; margin-bottom: 14px; }
  .btn { padding: 10px 36px; font-size: 15px; margin-bottom: 14px; }
  .controls { font-size: 11px; line-height: 1.8; }
  .tip { font-size: 11px; }

  #topbar { top: calc(6px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); transform: translateX(-50%) scale(0.78); transform-origin: top center; }
  .score-block { padding: 5px 12px; }
  .score-block .num { font-size: 16px; }
  .score-block.center .label { font-size: 11px; }

  #topControls { left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); top: calc(48px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); gap: 6px; }
  .top-btn { width: 36px; height: 36px; font-size: 14px; }

  #minimapWrap { width: 96px; height: 96px; right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); top: calc(48px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }

  #vitals { left: 10px; bottom: calc(8px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 5px; }
  .vital .bar { width: 110px; height: 10px; }
  .vital span:not(.icon) { width: 28px; font-size: 13px; }
  .vital .icon { font-size: 14px; width: 18px; }

  #weaponHud { right: calc(12px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); bottom: auto; top: calc(150px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  #ammo { font-size: 24px; }
  #weaponName { font-size: 11px; }
  #weaponSlots { gap: 5px; }
  .slot { padding: 2px 6px; font-size: 10px; }

  #dpad { width: 100px; height: 100px; left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); bottom: calc(56px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 4px; }
  .dpad-btn { font-size: 15px; border-radius: 8px; }

  #actionBtns { right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); bottom: calc(8px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .act-btn { width: 44px; height: 44px; font-size: 13px; }
  .fire-btn { width: 58px; height: 58px; font-size: 15px; }

  #toast { bottom: 150px; font-size: 13px; }
  #killFeed { top: 92px; left: 10px; }
}

/* ---- 极端小屏兜底（老机型/折叠屏）：在竖屏/矮横屏基础上进一步压缩 ---- */
@media (orientation: portrait) and (max-width: 340px) {
  #dpad { width: 96px; height: 96px; bottom: calc(88px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  .dpad-btn { font-size: 14px; }
  #actionBtns { bottom: calc(140px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .act-btn { width: 44px; height: 44px; font-size: 13px; }
  .fire-btn { width: 58px; height: 58px; font-size: 15px; }
  #vitals { left: 8px; }
  .vital .bar { width: 100px; }
  #weaponHud { right: 8px; }
  #ammo { font-size: 24px; }
  #minimapWrap { width: 92px; height: 92px; }
  #topControls { gap: 4px; }
  .top-btn { width: 34px; height: 34px; font-size: 14px; }
}

@media (orientation: landscape) and (max-height: 380px) {
  #dpad { width: 88px; height: 88px; bottom: calc(48px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  .dpad-btn { font-size: 13px; }
  #actionBtns { gap: 4px; }
  .act-btn { width: 40px; height: 40px; font-size: 12px; }
  .fire-btn { width: 52px; height: 52px; font-size: 14px; }
  #vitals { gap: 4px; }
  .vital .bar { width: 92px; height: 9px; }
  #weaponHud { top: calc(138px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  #ammo { font-size: 21px; }
  #minimapWrap { width: 84px; height: 84px; }
  #topControls { top: calc(42px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  .top-btn { width: 32px; height: 32px; font-size: 13px; }
  #killFeed { top: 86px; }
  #toast { bottom: 130px; font-size: 12px; }
}
